/**
 * Test stub for `@deepseek-ai/schemastery`.
 *
 * The plugin only needs the schema *builders* to exist at class-definition time
 * (a row's `static Config` is what turns it into a settings namespace) and the
 * `.volatile()` marker to be chainable. Validation itself happens in the host,
 * which this harness does not run, so every node records its metadata and
 * nothing more.
 */

function makeNode(kind, extra = {}) {
  const meta = { type: kind, ...extra };
  const node = {
    _type: kind,
    _meta: meta,
    default(value) {
      meta.default = value;
      return node;
    },
    description(text) {
      meta.description = text;
      return node;
    },
    min(value) {
      meta.min = value;
      return node;
    },
    max(value) {
      meta.max = value;
      return node;
    },
    step(value) {
      meta.step = value;
      return node;
    },
    role(value) {
      meta.role = value;
      return node;
    },
    required(value = true) {
      meta.required = value;
      return node;
    },
    volatile() {
      meta.volatile = true;
      return node;
    },
    toJSON() {
      return { type: kind, meta: { ...meta } };
    },
  };
  return node;
}

const z = {
  string: () => makeNode("string"),
  number: () => makeNode("number"),
  boolean: () => makeNode("boolean"),
  const: (value) => makeNode("const", { value }),
  union: (list) => makeNode("union", { list }),
  object: (dict) => makeNode("object", { dict }),
  array: (inner) => makeNode("array", { inner }),
  dict: (inner) => makeNode("dict", { inner }),
  any: () => makeNode("any"),
};

export default z;
export { z };